def min_sumset(m, n):
    import itertools
    min_size = float('inf')
    # We want to find a subset A of {0, 1, ..., m} such that |A| = n and max(A) = m.
    # This is equivalent to choosing n-1 elements from {0, 1, ..., m-1} including 0.
    # Wait, the set A must have n elements, and 0 and m are in A.
    # So we need to choose n-2 elements from {1, 2, ..., m-1}.
    for combo in itertools.combinations(range(1, m), n-2):
        A = sorted(list(combo) + [0, m])
        # Check if A has n elements and max(A) = m
        if len(A) == n and max(A) == m:
            sumset = set()
            for i in range(len(A)):
                for j in range(i, len(A)):
                    sumset.add(A[i] + A[j])
            min_size = min(min_size, len(sumset))
    return min_size

