def solve_small(n, M):
    min_sums = float('inf')
    # We need to choose n-2 elements from {1, 2, ..., M-1}
    # Total elements in T will be (n-2) + 2 = n
    for combo in combinations(range(1, M), n - 2):
        T = sorted([0] + list(combo) + [M])
        sums = set()
        for i in range(len(T)):
            for j in range(i, len(T)):
                sums.add(T[i] + T[j])
        min_sums = min(min_sums, len(sums))
    return min_sums

