def solve():
    k = 87
    T = 171
    min_sumset = float('inf')

    # Try A = {0, 1, ..., k-2, T}
    A1 = list(range(k-1)) + [T]
    min_sumset = min(min_sumset, get_sumset_size(A1))

    # Try A = {0, T-k+2, ..., T}
    A2 = [0] + list(range(T-k+2, T+1))
    min_sumset = min(min_sumset, get_sumset_size(A2))

    # Try A = {0, d, 2d, ..., (k-2)d, T} for all d
    for d in range(1, T + 1):
        A = []
        for i in range(k-1):
            A.append(i*d)
        A.append(T)
        A = sorted(list(set([x for x in A if 0 <= x <= T])))
        if len(A) == k and A[0] == 0 and A[-1] == T:
            min_sumset = min(min_sumset, get_sumset_size(A))

    # Try A = {0, T-d, T-2d, ..., T-(k-2)d}
    for d in range(1, T + 1):
        A = [0]
        for i in range(k-1):
            A.append(T - i*d)
        A = sorted(list(set([x for x in A if 0 <= x <= T])))
        if len(A) == k and A[0] == 0 and A[-1] == T:
            min_sumset = min(min_sumset, get_sumset_size(A))

    # Try A = {0, d, 2d, ..., (k-2)d, T} where we try all possible m, n
    # A = {0, 1, ..., m} U {T-n, ..., T}
    # Here m+n = k-2
    for n in range(k-1):
        m = k-2-n
        A = list(range(m+1)) + list(range(T-n, T+1))
        A = sorted(list(set(A)))
        if len(A) == k and A[0] == 0 and A[-1] == T:
            min_sumset = min(min_sumset, get_sumset_size(A))

    # Try A = {0, d, 2d, ..., m*d} U {T-n, ..., T}
    # This is like the same as above but the first block is an AP with difference d.
    for d in range(1, T + 1):
        for n in range(k-1):
            m = k-2-n
            # First block: 0, d, 2d, ..., m*d (m+1 elements)
            # Second block: T-n, T-n+1, ..., T (n+1 elements)
            A = []
            for i in range(m+1):
                A.append(i*d)
            for i in range(n+1):
                A.append(T-i)
            A = sorted(list(set([x for x in A if 0 <= x <= T])))
            if len(A) == k and A[0] == 0 and A[-1] == T:
                min_sumset = min(min_sumset, get_sumset_size(A))

    print(f"Result: {min_sumset}")

